import{_ as e,c as l,o as n,a3 as a}from"./chunks/framework.BusRvirq.js";const f=JSON.parse('{"title":"화면 UI/UX 설계 및 스토리보드 승인 확인서 (UI Design Sign-off)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/06_UI_Design_Signoff_template.html"}]]},"headers":[],"relativePath":"public/templates/06_UI_Design_Signoff_template.md","filePath":"public/templates/06_UI_Design_Signoff_template.md","lastUpdated":1790810085000}'),s={name:"public/templates/06_UI_Design_Signoff_template.md"};function r(d,t,i,g,o,x){return n(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="화면-ui-ux-설계-및-스토리보드-승인-확인서-ui-design-sign-off" tabindex="-1">화면 UI/UX 설계 및 스토리보드 승인 확인서 (UI Design Sign-off) <a class="header-anchor" href="#화면-ui-ux-설계-및-스토리보드-승인-확인서-ui-design-sign-off" aria-label="Permalink to “화면 UI/UX 설계 및 스토리보드 승인 확인서 (UI Design Sign-off)”">​</a></h1><p>본 문서는 [발주회사명] (이하 &quot;발주처&quot;라 한다)과 주식회사 엠파시 (이하 &quot;수행사&quot;라 한다)가 진행 중인 [프로젝트명]의 <strong>Phase 2 (상세 설계 단계)</strong> 중 프론트엔드 화면 UI/UX 프로토타입 및 화면 설계서(스토리보드)를 최종 검토·승인하기 위해 작성하는 서면 확인서입니다.</p><hr><h3 id="_1-대상-화면-산출물-개요" tabindex="-1">1. 대상 화면 산출물 개요 <a class="header-anchor" href="#_1-대상-화면-산출물-개요" aria-label="Permalink to “1. 대상 화면 산출물 개요”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명</strong></td><td style="text-align:left;">[계약서상 사업명]</td></tr><tr><td style="text-align:left;"><strong>검토 대상 문서</strong></td><td style="text-align:left;">화면 설계서 (스토리보드 v1.0) 및 Figma 인터랙티브 프로토타입</td></tr><tr><td style="text-align:left;"><strong>문서 / 프로토타입 링크</strong></td><td style="text-align:left;">[Figma URL 또는 사내 형상관리 문서 경로]</td></tr><tr><td style="text-align:left;"><strong>검토 일자</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일 (총 [ ] 회 합동 워크숍 실시)</td></tr><tr><td style="text-align:left;"><strong>총 설계 화면 수</strong></td><td style="text-align:left;">총 [ ] 개 화면 (대메뉴 [ ] 개, 중메뉴 [ ] 개, 팝업/모달 [ ] 개)</td></tr></tbody></table><hr><h3 id="_2-메뉴-그룹별-화면-설계-승인-내역" tabindex="-1">2. 메뉴 그룹별 화면 설계 승인 내역 <a class="header-anchor" href="#_2-메뉴-그룹별-화면-설계-승인-내역" aria-label="Permalink to “2. 메뉴 그룹별 화면 설계 승인 내역”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">대메뉴</th><th style="text-align:center;">화면 ID 범위</th><th style="text-align:left;">주요 화면 명칭</th><th style="text-align:center;">화면 수</th><th style="text-align:center;">발주처 담당 검토자</th><th style="text-align:center;">승인 여부</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>시스템 관리</strong></td><td style="text-align:center;">SYS-001 ~ 015</td><td style="text-align:left;">사용자 관리, 권한 설정, 메뉴 관리, 코드 관리</td><td style="text-align:center;">15</td><td style="text-align:center;">[직급 성명]</td><td style="text-align:center;">[ v ] 승인</td></tr><tr><td style="text-align:left;"><strong>업무 메인 (대시보드)</strong></td><td style="text-align:center;">DASH-001 ~ 005</td><td style="text-align:left;">종합 모니터링, KPI 위젯, 알림 센터</td><td style="text-align:center;">5</td><td style="text-align:center;">[직급 성명]</td><td style="text-align:center;">[ v ] 승인</td></tr><tr><td style="text-align:left;"><strong>핵심 업무 도메인 1</strong></td><td style="text-align:center;">BIZ1-001 ~ 020</td><td style="text-align:left;">주문/계약 접수, 상세 조회, 승인 결재</td><td style="text-align:center;">20</td><td style="text-align:center;">[직급 성명]</td><td style="text-align:center;">[ v ] 승인</td></tr><tr><td style="text-align:left;"><strong>핵심 업무 도메인 2</strong></td><td style="text-align:center;">BIZ2-001 ~ 018</td><td style="text-align:left;">상품/서비스 등록, 재고/현황 관리</td><td style="text-align:center;">18</td><td style="text-align:center;">[직급 성명]</td><td style="text-align:center;">[ v ] 승인</td></tr><tr><td style="text-align:left;"><strong>통계 및 보고서</strong></td><td style="text-align:center;">RPT-001 ~ 008</td><td style="text-align:left;">기간별 분석, 데이터 다운로드, 정산 리포트</td><td style="text-align:center;">8</td><td style="text-align:center;">[직급 성명]</td><td style="text-align:center;">[ v ] 승인</td></tr><tr><td style="text-align:left;"><strong>공통 모달 컴포넌트</strong></td><td style="text-align:center;">MDL-001 ~ 012</td><td style="text-align:left;">상세 팝업, 이력 조회, 파일 업로드 등</td><td style="text-align:center;">12</td><td style="text-align:center;">[직급 성명]</td><td style="text-align:center;">[ v ] 승인</td></tr><tr><td style="text-align:left;"><strong>합계</strong></td><td style="text-align:center;">-</td><td style="text-align:left;"><strong>총 화면 수</strong></td><td style="text-align:center;"><strong>[ ] 개</strong></td><td style="text-align:center;">-</td><td style="text-align:center;"><strong>전체 승인</strong></td></tr></tbody></table><hr><h3 id="_3-승인-조건-및-레이아웃-변경-통제-원칙" tabindex="-1">3. 승인 조건 및 레이아웃 변경 통제 원칙 <a class="header-anchor" href="#_3-승인-조건-및-레이아웃-변경-통제-원칙" aria-label="Permalink to “3. 승인 조건 및 레이아웃 변경 통제 원칙”">​</a></h3><ol><li><strong>화면 골격 및 컴포넌트 구조의 확정</strong>: <ul><li>발주처는 제출된 화면 설계서의 정보 구조(IA), 컴포넌트 배치, 입력 필드 항목 및 유효성 검증 규칙이 현업의 업무 요건을 충족함을 확인하고 이를 승인합니다.</li></ul></li><li><strong>개발 단계에서의 임의 화면 개편 제한</strong>: <ul><li>본 승인 이후 프론트엔드 퍼블리싱 및 컴포넌트 개발(Phase 3)이 시작되며, 본 승인본과 다른 대규모 레이아웃 변경, 화면 분할/통합, 신규 그리드 추가 요구는 변경 요청(CR) 대상이 되며 추가 공수가 산정됩니다.</li></ul></li><li><strong>디테일 스타일 가이드 준수</strong>: <ul><li>글꼴, 색상 테마, 반응형 브레이크포인트, 접근성 기준은 사전에 합의된 프레임워크 디자인 시스템(BasicModal 표준 및 Ant Design Vue 가이드)을 따릅니다.</li></ul></li></ol><hr><h3 id="_4-잔여-보완-요청-사항-사소한-문구-및-필드-레이블-조정" tabindex="-1">4. 잔여 보완 요청 사항 (사소한 문구 및 필드 레이블 조정) <a class="header-anchor" href="#_4-잔여-보완-요청-사항-사소한-문구-및-필드-레이블-조정" aria-label="Permalink to “4. 잔여 보완 요청 사항 (사소한 문구 및 필드 레이블 조정)”">​</a></h3><p>본 승인과 별개로 개발 진행 중에 반영하기로 합의한 사소한 레이블/문구 수정 내역입니다. (구조 변경 없음)</p><table tabindex="0"><thead><tr><th style="text-align:center;">화면 ID</th><th style="text-align:left;">기존 항목명</th><th style="text-align:left;">변경 합의 항목명</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>BIZ1-004</strong></td><td style="text-align:left;">&quot;주문 접수자&quot;</td><td style="text-align:left;">&quot;신청 담당자&quot;</td><td style="text-align:left;">용어 표준화 반영</td></tr><tr><td style="text-align:center;"><strong>SYS-003</strong></td><td style="text-align:left;">&quot;권한 그룹 코드&quot;</td><td style="text-align:left;">&quot;역할 식별자 (Role ID)&quot;</td><td style="text-align:left;">사용자 가이드 용어 일치</td></tr></tbody></table><hr><p>본 확인서에 기재된 화면 설계서 및 프로토타입의 내용을 충분히 검토하였으며, 개발 단계(Phase 3) 착수에 동의함을 확인합니다.</p><p><strong>승인일자: 202 년 월 일</strong></p><p><strong>[발주처 현업 부서 총괄]</strong></p><ul><li>소속 부서: [ ]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul><p><strong>[발주처 IT 개발 총괄]</strong></p><ul><li>소속 부서: [ ]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul><p><strong>[수행사 화면설계/UI 총괄 PL]</strong></p><ul><li>소속 부서: [주식회사 엠파시 기술본부]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul>',24)])])}const h=e(s,[["render",r]]);export{f as __pageData,h as default};
